INSERT INTO `movie` VALUES (1,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'Amy Sedaris, Jeff Goldblum, James Marsden','Hoạt Hình','Tom McGrath',105,2,'Tiếng Anh với phụ đề tiếng Việt và lồng tiếng Việt','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_boss_baby_2_24.12.2021_1_1_1__1.jpg','Nhóc trùm Ted giờ đây đã trở thành một triệu phú nổi tiếng trong khi Tim lại có một cuộc sống đơn giản bên vợ anh Carol và hai cô con gái nhỏ yêu dấu. Mỗi mùa Giáng sinh tới, cả Tina và Tabitha đều mong được gặp chú Ted nhưng dường như hai anh em nhà Templeton nay đã không còn gần gũi như xưa. Nhưng bất ngờ thay khi Ted lại có màn tái xuất không thể hoành tráng hơn khi đáp thẳng máy bay trực thăng tới nhà Tim trước sự ngỡ ngàng của cả gia đình.','Nhóc Trùm: Nối Nghiệp Gia Đình','P - PHIM DÀNH CHO MỌI ĐỐI TƯỢNG','2021-12-24','Nhóc trùm Ted giờ đây đã trở thành một triệu phú nổi tiếng trong khi Tim lại có một cuộc sống đơn giản bên vợ anh Carol và hai cô con gái nhỏ yêu dấu.','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_boss_baby_2_24.12.2021_1_1_1__1.jpg','https://www.youtube.com/embed/Lv8nL2q8yRI'),(2,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'Tom Hardy, Michelle Williams, Woody Harrelson, Naomie Harris','Hành Động, Khoa Học Viễn Tưởng, Phiêu Lưu, Thần thoại','Andy Serkis',97,2,'Tiếng Anh - Phụ đề Tiếng Việt','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_venom_121121_1__1.jpg','Siêu bom tấn VENOM: LET THERE BE CARNAGE hứa hẹn trận chiến khốc liệt nhất giữa Venom và kẻ thù truyền kiếp, Carnage.','Venom: Đối Mặt Tử Thù','C13 - PHIM CẤM KHÁN GIẢ DƯỚI 13 TUỔI','2021-12-10','Siêu bom tấn VENOM: LET THERE BE CARNAGE hứa hẹn trận chiến khốc liệt nhất giữa Venom và kẻ thù truyền kiếp, Carnage.','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_venom_121121_1__1.jpg','https://www.youtube.com/embed/EVWdzVtSh1I'),(3,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'Keanu Reeves, Carrie-Anne Moss, Yahya Abdul-Mateen II, Jessica Henwick','Hành Động, Khoa Học Viễn Tưởng','Lana Wachowski',148,2,'Tiếng Anh - Phụ đề Tiếng Việt, Phụ đề Tiếng Hàn','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_matrix_4_1__1.jpg','Ma Trận: Hồi Sinh là phần phim tiếp theo rất được trông đợi của loạt phim Ma Trận đình đám, đã góp phần tái định nghĩa thể loại phim khoa học viễn tưởng.','Ma Trận: Hồi Sinh','C18 - PHIM CẤM KHÁN GIẢ DƯỚI 18 TUỔI','2021-12-24','Sau 20 năm, siêu phẩm ma trận đã trở lại với người xem, Neo is back!','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_matrix_4_1__1.jpg','https://www.youtube.com/embed/l2UTOJC5Tbk'),(4,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'Wasabi Mizuta, Megumi Oohara, Yumi Kakazu, Subaru Kimura','Hài, Hoạt Hình','Ryuichi Yagi, Takashi Yamazaki',96,2,'Tiếng Nhật - Phụ đề Tiếng Việt; Lồng tiếng','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_doremon_2_1__1.jpg','Một ngày nọ, Nobita vô tình tìm thấy chú gấu bông cũ, món đồ chơi chất chứa bao kỉ niệm cùng người bà đáng kính. Với khát khao muốn gặp bà lần nữa, Nobita đã trở về quá khứ bằng cổ máy thời gian.','Doraemon: Ôi Bạn Ơi 2','P - PHIM DÀNH CHO MỌI ĐỐI TƯỢNG','2021-12-17','Một ngày nọ, Nobita vô tình tìm thấy chú gấu bông cũ, món đồ chơi chất chứa bao kỉ niệm cùng người bà đáng kính.','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_doremon_2_1__1.jpg','https://www.youtube.com/embed/GXnOs4Hj8MA'),(5,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'Ansel Elgort, Rachel Zegler, Ariana DeBose, David Alvarez, Mike Faist','Nhạc kịch, Tình cảm','Steven Spielberg',156,2,'Tiếng Anh - Phụ đề Tiếng Việt','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_wss_1200x1800__1.jpg','Được đạo diễn bởi đạo diễn gạo cội từng giành giải Oscar Steven Spielberg, cùng kịch bản bởi biên kịch từng giành giải Pulitzer Prize và giải Tony Award.','Câu Chuyện Phía Tây','C16 - PHIM CẤM KHÁN GIẢ DƯỚI 16 TUỔI','2021-12-24','Câu chuyện phía Tây kể lại câu chuyện tình yêu kinh điển của Tony và Maria.','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_wss_1200x1800__1.jpg','https://www.youtube.com/embed/QPvqV71P0Fo'),(6,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'JISOO, JENNIE, ROSÉ, LISA','Phim tài liệu','Su Yee Jung, Oh Yoon-Dong',99,2,'Tiếng Hàn - Phụ đề tiếng Việt','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_blackpink_vie_2_1__1.jpg','Nhóm nhạc nữ được yêu thích toàn cầu, BLACKPINK sẽ kỷ niệm năm thứ 5 hoạt động của nhóm với việc phát hành BLACKPINK THE MOVIE, đây cũng như là món quà đặc biệt dành tặng cho các BLINK.','BlackPink The Movie','P - PHIM DÀNH CHO MỌI ĐỐI TƯỢNG','2021-12-24','Nhóm nhạc nữ được yêu thích toàn cầu, BLACKPINK sẽ kỷ niệm năm thứ 5 hoạt động của nhóm.','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/p/o/poster_blackpink_vie_2_1__1.jpg','https://www.youtube.com/embed/Q_rK9UlUN-Q'),(7,'2026-08-20 15:55:18.000000','2026-08-20 15:55:18.000000',NULL,NULL,'Tom Holland, Zendaya, Benedict Cumberbatch, Jacob Batalon, Jon Favreau','Hành Động, Phiêu Lưu','Jon Watts',149,2,'Tiếng Anh - Phụ đề Tiếng Việt','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/s/n/snwh_poster_bluemontage_4x5fb_1__1.jpg','Lần đầu tiên trong lịch sử điện ảnh của Người Nhện, thân phận người hàng xóm thân thiện bị lật mở, khiến trách nhiệm làm một Siêu Anh Hùng xung đột với cuộc sống bình thường.','Người Nhện: Không Còn Nhà','C13 - PHIM CẤM KHÁN GIẢ DƯỚI 13 TUỔI','2021-12-17','Đa vũ trụ được mở ra, những kẻ phản diện nào sẽ trạm chán spidey, cùng đón xem nhá','https://www.cgv.vn/media/catalog/product/cache/1/small_image/240x388/dd828b13b1cb77667d034d5f59a82eb6/s/n/snwh_poster_bluemontage_4x5fb_1__1.jpg','https://www.youtube.com/embed/daHCu_jU5mQ'),(8,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Cody Nam Võ, NSƯT Cao Minh, Huỳnh Lập, Hồng Ánh, Hứa Vĩ Văn, Tín Nguyễn','Hài, Gia Đình','Huỳnh Lập',110,1,'Tiếng Việt','/img/movies/nghi-he-so-nghi-huu-1_1786436532090.jpg','Nghỉ Hè Sợ Nghỉ Hưu xoay quanh người cháu trai thuộc thế hệ Z - Trí Bình và người ông nội là cựu chiến binh - ông Thời. Giữa hai ông cháu có sự đối lập rõ rệt khi một bên là vẻ hiện đại, thời thượng đặc trưng của người trẻ và một bên là nét truyền thống, nghiêm trang của người lính. Nếu ông Thời luôn trăn trở về những ký ức xưa và khát khao tìm được đồng đội thời chiến tranh, thì Trí Bình lại loay hoay đối mặt với khủng hoảng đi tìm sự rực rỡ cho mình ở đời sống hiện tại.','Nghỉ Hè Sợ Nghỉ Hưu','T13','2026-08-21','Nghỉ Hè Sợ Nghỉ Hưu xoay quanh người cháu trai thế hệ Z Trí Bình và người ông nội cựu chiến binh Thời.','/img/movies/nghi-he-so-nghi-huu.jpg','https://www.youtube.com/embed/RgFO3duBbPw'),(9,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Tom Holland, Zendaya, Sadie Sink, Jacob Batalon, Mark Ruffalo','Giả Tưởng, Hành Động, Phiêu Lưu','Destin Daniel Cretton',145,1,'Tiếng Anh - Phụ đề Tiếng Việt','/img/movies/spiderman-brand-new-day-1_1784708435729.jpg','Bốn năm sau các sự kiện trước, Peter giờ đã trưởng thành và sống hoàn toàn một mình, khi anh tự nguyện xóa bản thân khỏi cuộc sống và ký ức của những người mình yêu thương. Trong một New York không còn ai biết đến danh tính của mình, anh dốc toàn lực làm người hùng trở thành Spider-Man toàn thời gian để bảo vệ thành phố. Tuy nhiên, khi áp lực ngày càng gia tăng, nó kích hoạt một sự biến đổi thể chất bất ngờ, đe dọa chính sự tồn tại của anh. Đồng thời, một chuỗi tội phạm bí ẩn mới xuất hiện, kéo theo một trong những mối đe dọa mạnh mẽ nhất mà Spider-Man từng đối mặt.','Người Nhện: Khởi Đầu Mới','T13','2026-07-31','Bốn năm sau các sự kiện trước, Peter giờ đã trưởng thành và sống hoàn toàn một mình làm Spider-Man toàn thời gian.','/img/movies/spiderman-brand-new-day-2_1784708394982.jpg','https://www.youtube.com/embed/b_FbrHg9118'),(10,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Ewan McGregor, Anne Hathaway','Kinh Dị, Bí Ẩn','David Robert Mitchell',105,1,'Tiếng Anh - Phụ đề Tiếng Việt','/img/movies/pho-oak-500_1782273857915.jpg','Sau khi một thảm họa thiên nhiên xé toạc Phố Oak khỏi khu ngoại ô và đưa con phố đến một nơi xa lạ, gia đình Platt nhanh chóng nhận ra rằng chỉ bằng cách luôn đứng bên nhau, họ mới có thể vượt qua vận mệnh nghiệt ngã này.','Ngày Tàn Của Phố Oak','T13','2026-08-14','Sau khi một thảm họa thiên nhiên xé toạc Phố Oak, gia đình Platt phải kề vai sát cánh vượt qua vận mệnh nghiệt ngã.','/img/movies/pho-oak-500_1782273857915.jpg','https://www.youtube.com/embed/MwqWi3L4Kvk'),(11,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Lý Tư Đồng, Vương Ngạn Đồng, Ngô Thiếu Khanh','Tâm Lý, Gia Đình','Lam Hồng Xuân',115,1,'Tiếng Trung - Phụ đề Tiếng Việt','/img/movies/thu-tinh-gui-ngoai-500_1784276463437.jpg','Tác phẩm lấy bối cảnh Trung Quốc, Thái Lan từ thập niên 1950 tới hiện tại, nói về cuộc đời của bà Diệp Thục Như (Ngô Thiếu Khanh đóng). Xuất thân tiểu thư, bà trốn nhà đi theo chàng trai nghèo Trịnh Mộc Sinh (Vương Ngạn Đồng đóng), sinh ba người con. Vì biến cố chính trị, ông Mộc Sinh phiếu bạt tới Thái Lan, ở đây làm lụng kiếm tiền gửi về cho vợ con. Trịnh Mộc Sinh đầu óc nhanh nhạy, giỏi kiếm tiền, trợ cấp đủ đầy cho gia đình và một lòng một dạ với vợ. Đôi vợ chồng gửi gắm tình yêu qua những lá thư.','Thư Tình Gửi Ngoại','T13','2026-08-07','Câu chuyện gia đình ấm áp, giàu nghĩa tình sau những lá thư mà Trịnh Mộc Sinh gửi cho vợ suốt nhiều thập kỷ.','/img/movies/thu-tinh-gui-ngoai-500_1784276463437.jpg','https://www.youtube.com/embed/eaFBU-Tp8lA'),(12,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Matt Damon, Tom Holland, Charlize Theron, Anne Hathaway, Jon Bernthal, Zendaya, Lupita Nyong o, Robert Pattinson','Hành Động, Lịch Sử, Phiêu Lưu','Christopher Nolan',155,1,'Tiếng Anh - Phụ đề Tiếng Việt','/img/movies/hinh-1-14.jpg','Theo chân Odysseus trong hành trình trở về nhà sau cuộc chiến thành Troy, tràn ngập thử thách như cuộc chạm trán của ông với Polyphemus, các nàng tiên cá, Circe và kết thúc bằng cuộc đoàn tụ với vợ mình, Penelope.','The Odyssey: Khúc Ca Khải Hoàn','T16','2026-07-17','Theo chân Odysseus trong hành trình trở về nhà sau cuộc chiến thành Troy đầy hiểm nguy và gian nan.','/img/movies/the-oddysey-500_1778060370554.jpg','https://www.youtube.com/embed/hk0JVCJ8NOA'),(13,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Amelia Eve, Island Austin, Lin Shaye','Kinh Dị','Jacob Chase',108,1,'Tiếng Anh - Phụ đề Tiếng Việt','/img/movies/insidious-sneak-2048_1786436889562.jpg','Quỷ Quyệt: Ranh Giới Vô Định xoay quanh Gemma (Amelia Eve), một bà mẹ trẻ trở về sống trong ngôi nhà thời thơ ấu cùng con gái và phát hiện mình có thể bước vào Cõi Vô Định, nơi giam giữ những linh hồn lạc lối. Nhưng Gemma không chỉ có thể bước vào Cõi Vô Định, cô còn sở hữu năng lực đưa những thực thể từ đó trở về thế giới thực. Khi các thế lực tà ác phát hiện ra sức mạnh này, ranh giới giữa hai thế giới dần sụp đổ, biến thế giới của người sống thành sân chơi của quỷ dữ.','Quỷ Quyệt: Ranh Giới Vô Định','T16','2026-08-21','Gemma phát hiện mình có thể bước vào Cõi Vô Định và đưa những thực thể từ đó trở về thế giới thực.','/img/movies/insidious-sneak-500_1786436825174.jpg','https://www.youtube.com/embed/bmDLI7kCPPw'),(14,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Kobayashi Yumiko, Narahashi Miki, Morikawa Toshiyuki, Koorogi Satomi','Hoạt Hình, Giả Tưởng','Watanabe Masaki',98,1,'Tiếng Nhật - Lồng tiếng & Phụ đề Tiếng Việt','/img/movies/shin-chan-500_1785817182150.jpg','Lấy bối cảnh mùa hè tại Akita, bộ phim theo chân Shin và gia đình Nohara trong chuyến về quê đầy háo hức. Tuy nhiên, một sự kiện kỳ lạ đã đưa cả gia đình lạc vào Xứ sở Yêu quái bí ẩn – nơi con người không được phép đặt chân tới. Tại đây, Shin và gia đình phải đối mặt với những thử thách chưa từng có, đồng thời gặp gỡ hàng loạt yêu quái độc đáo, hài hước và đáng yêu.','Shin Cậu Bé Bút Chì: Xứ Sở Yêu Quái','P','2026-08-21','Shin và gia đình Nohara lạc vào Xứ sở Yêu quái bí ẩn trong chuyến về quê mùa hè đầy bất ngờ.','/img/movies/shin-chan-500_1785817182150.jpg','https://www.youtube.com/embed/7PsrUVHTfUo'),(15,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Shin Min Ah, Kim Nam Hee, Lee Seung Ryong','Tội Phạm, Giật Gân','Yeom Ji Ho',112,1,'Tiếng Hàn - Phụ đề Tiếng Việt','/img/movies/diem-mu-500_1785986748944.jpg','Phát hiện người chị em song sinh qua đời bất thường dưới vỏ bọc tự sát, Seo-jin (Shin Min-A) quyết tâm dấn thân vào cuộc săn đuổi vạch mặt kẻ thủ ác. Đối mặt với căn bệnh di truyền đang rút cạn thị lực từng ngày và chính bản thân cô trở thành mục tiêu tiếp theo của kẻ sát nhân, hành trình giải mã ma trận tâm lý và truy lùng hung thủ của Seo-jin trở nên căng thẳng và nguy cấp hơn bao giờ hết.','Điểm Mù (Blind Spot)','T18','2026-08-14','Seo-jin quyết tâm dấn thân vào cuộc săn đuổi vạch mặt kẻ thủ ác sát hại người chị em song sinh.','/img/movies/diem-mu-500_1785986748944.jpg','https://www.youtube.com/embed/rhrv7w4EwUo'),(16,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Kaname Jun, Kashu Toshiki, Yamasaki Jun','Hành Động','Tasaki Ryuta',95,1,'Tiếng Nhật - Phụ đề Tiếng Việt','/img/movies/agito-adaptation-main-website-1200-x-1800-_1785138379150.jpg','Agito: Psychic War kể về thế giới nơi mà con người bắt đầu thức tỉnh những năng lực siêu nhiên, hậu quả kéo theo đó là sự hỗn loạn dần trở nên mất kiểm soát. Với ý chí sắt đá của mình, viên cảnh sát Makoto Hikawa sẽ là người dám đứng lên chiến đấu giữa thế giới đầy biến động này.','Kamen Rider Agito: Psychic War','T16','2026-08-14','Viên cảnh sát Makoto Hikawa dũng cảm đứng lên chiến đấu khi năng lực siêu nhiên thức tỉnh khắp nơi.','/img/movies/agito-adaptation-main-website-1200-x-1800-_1785138379150.jpg','https://www.youtube.com/embed/itCosOs0_T0'),(17,'2026-08-20 16:36:06.000000','2026-08-20 16:36:06.000000','admin','admin','Kamiya Hiroshi, Kaji Yuuki, Ishikawa Yui','Hoạt Hình','Hayashi Yuichiro',145,1,'Tiếng Nhật - Phụ đề Tiếng Việt','/img/movies/attack-on-titan-2_1785484162552.jpg','Attack on Titan the Movie: The Last Attack sẽ đưa trận chiến dữ dội nhất của Eren Yeager lên màn ảnh rộng. Trong cuộc chiến cuối cùng định đoạt số phận thế giới, Eren Yeager đã giải phóng sức mạnh tối thượng của các Titan. Dẫn đầu đội quân Titan Đại hình khổng lồ, Eren quyết tâm hủy diệt mọi kẻ thù đe dọa đến quê hương Eldia.','Attack on Titan: The Last Attack','T16','2026-08-14','Trận chiến cuối cùng định đoạt số phận thế giới giữa Eren Yeager cùng đội quân Titan Đại hình và nhân loại.','/img/movies/attack-on-titan-2_1785484162552.jpg','https://www.youtube.com/embed/YfQ7Ftv_Sqg'),(18,'2026-08-20 23:41:17.000000',NULL,NULL,NULL,'Dafne Keen, Sophie Nélisse, Sky Yang','Kinh Dị','Corin Hardy',105,0,'Tiếng Anh - Phụ đề Tiếng Việt','/img/coi-bao-tu-500_1786683120850.jpg','Một nhóm học sinh cá biệt vô tình nhặt được một cổ vật Aztec bị nguyền rủa. Mỗi khi tiếng còi ám ảnh ấy cất lên, nó không chỉ xé tan không gian bằng âm thanh rợn người, mà còn đánh thức và triệu hồi chính \"cái chết trong tương lai\" của từng người tìm đến đi săn họ. Liệu nhóm bạn có thể giải mã bí ẩn của lời nguyền trước khi từng người một phải đối mặt với kết cục thảm khốc của chính mình?','Còi Báo Tử','T18','2026-08-21','Một nhóm học sinh vô tình nhặt được một cổ vật Aztec bị nguyền rủa mỗi khi tiếng còi ám ảnh ấy cất lên.','/img/coi-bao-tu-500_1786683120850.jpg','https://www.youtube.com/watch?v=bkkTCq_utMY'),(19,'2026-08-20 23:41:17.000000',NULL,NULL,NULL,'Quách Ngọc Ngoan, Tuấn Trần, Johnny Trí Nguyễn, NSND Tự Long, Hứa Vĩ Văn, Trần Thiên Tú, Đỗ Thị Hải Yến','Hành Động, Tâm Lý','Nguyễn Phan Quang Bình',118,0,'Tiếng Việt','/img/ho-linh-trang-si_1785837646697.jpg','Cuối triều Đinh, vua Đinh Tiên Hoàng đột ngột băng hà khiến triều đình rơi vào khủng hoảng. Thù trong chưa yên, giặc ngoài đã lăm le xâm lược. Những tử sĩ được giao nhiệm vụ đưa linh cữu nhà vua đến long mạch để an táng. Cuộc hành trình nhiều cam go này trở thành chuyến đi thử thách lòng trung nghĩa...','Hộ Linh Tráng Sĩ','T13','2026-08-28','Cuối triều Đinh, vua Đinh Tiên Hoàng đột ngột băng hà khiến triều đình rơi vào khủng hoảng.','/img/ho-linh-trang-si_1785837646697.jpg','https://www.youtube.com/watch?v=z4VtBgfxawc'),(20,'2026-08-20 23:41:17.000000',NULL,NULL,NULL,'Abimana Aryasatya, Almanzo Konoralma, Aming Sugandhi','Kinh Dị','Joko Anwar',110,0,'Tiếng Indonesia - Phụ đề Tiếng Việt','/img/ma-tu-500_1786439829483.jpg','Một tù nhân bí ẩn xuất hiện trong một nhà tù khét tiếng bạo lực nhất Indonesia, mang theo một thực thể siêu nhiên chỉ săn lùng những kẻ có năng lượng tiêu cực. Để sống sót, các tù nhân buộc phải cùng nhau làm việc thiện nhằm xóa bỏ bóng tối trong tâm hồn. Hoặc chết từng người một.','Ma Tù','T18','2026-09-04','Một tù nhân bí ẩn xuất hiện trong một nhà tù khét tiếng bạo lực nhất Indonesia.','/img/ma-tu-500_1786439829483.jpg','https://www.youtube.com/watch?v=n8tqB1CUPQY'),(21,'2026-08-20 23:41:17.000000',NULL,NULL,NULL,'Nguyễn Cao Kỳ Duyên, Steven Nguyễn','Tâm Lý, Tình Cảm','Nguyễn Hữu Hoàng',115,0,'Tiếng Việt','/img/chi-chi-em-em-3-500_1786334475431.jpg','Giữa xã hội Bắc Bộ cũ đầy lễ giáo và những khuôn phép khắt khe, Thị Mầu – tiểu thư nổi tiếng tài sắc nhất vùng – bước vào một thế giới nơi tình yêu chưa bao giờ là chuyện của riêng hai người. Những rung động bị che giấu, những mối quan hệ chồng chéo và những lựa chọn trái với khuôn phép tạo nên một mạng nhện tình cảm rối ren.','Chị Chị Em Em 3','T18','2026-10-16','Giữa xã hội Bắc Bộ cũ đầy lễ giáo, Thị Mầu – tiểu thư tài sắc nhất vùng bước vào mạng nhện tình cảm rối ren.','/img/chi-chi-em-em-3-500_1786334475431.jpg','https://www.youtube.com/watch?v=-FO53PkM508'),(22,'2026-08-20 23:41:17.000000',NULL,NULL,NULL,'Brad Pitt, J.K. Simmons, Anna Lambe','Hành Động','David Ayer',125,0,'Tiếng Anh - Phụ đề Tiếng Việt','/img/trai-tim-quai-thu-500_1787041540613.jpg','Sau một vụ tai nạn máy bay kinh hoàng, sĩ quan Lực lượng Đặc nhiệm James Belmont (Brad Pitt) và chú chó chiến đấu Odin bị mắc kẹt giữa vùng hoang dã sâu thẳm của Alaska. Từ đó, họ buộc phải cùng nhau bước vào cuộc chiến sinh tồn khốc liệt trước thiên nhiên khắc nghiệt.','Trái Tim Quái Thú','T16','2026-09-25','Sĩ quan James Belmont và chú chó chiến đấu Odin bị mắc kẹt giữa vùng hoang dã Alaska.','/img/trai-tim-quai-thu-500_1787041540613.jpg','https://www.youtube.com/watch?v=aw7qSfmlwRk'),(23,'2026-08-20 23:41:17.000000',NULL,NULL,NULL,'Tom Cruise, Jesse Plemons, John Goodman','Hài, Giặt Gân','Alejandro González Iñárritu',120,0,'Tiếng Anh - Phụ đề Tiếng Việt','/img/digger-500_1769065542641.jpg','Digger. Trò cười rung chuyển cả thế giới. Dự kiến khởi chiếu tháng 10.2026.','Digger','T16','2026-10-02','Digger. Trò cười rung chuyển cả thế giới. Dự kiến khởi chiếu tháng 10.2026.','/img/digger-500_1769065542641.jpg','https://www.youtube.com/watch?v=-4fEnppaK5s');
